/* Darsi — ENGLISH content (translated from the French reference).
   Sources: 'q:S:V' = verse, 'h:name' = hadith (see HADITHS_REFS), 'f:name' = reference note below.
   Rule: every question must make sense on its own. Content to be reviewed by a qualified person. */
'use strict';
CONTENU.en={
lecons:{
/* ===================== RAMADAN & FASTING ===================== */
'r-bienvenue':{titre:"The month of Ramadan",
 texte:["Ramadan is the 9th month of the Muslim calendar, called the Hijri calendar. This calendar is lunar: each month begins when the new crescent moon appears.",
  "A lunar year has about 354 days. So Ramadan moves about ten days earlier every year in our calendar.",
  "It was during this month that the revelation of the Qur'an began. Fasting in Ramadan was made obligatory in the 2nd year of the Hijrah."],
 retenir:"Ramadan is the 9th lunar month, the month of the Qur'an and of fasting.",
 sources:['q:2:185','h:croissant'],
 quiz:[
  {q:"In the Muslim (Hijri) calendar, which month is Ramadan?",c:["The 9th month","The 1st month","The 12th month","The 7th month"],b:0,e:"Ramadan is the 9th month. The 1st month of the Hijri year is Muharram.",s:['f:mois']},
  {q:"Which celestial body is the Muslim (Hijri) calendar based on?",c:["The moon","The sun","The stars","None at all"],b:0,e:"Each month begins when the new crescent moon appears.",s:['q:2:189','h:croissant']},
  {q:"Why does the date of Ramadan move about 11 days earlier each year?",c:["Because the lunar year is shorter than the solar year","Because scholars shift it every year","Because the Hijri year has 13 months","Because it follows the Persian solar calendar"],b:0,e:"A lunar year has about 354 days, roughly 11 days fewer than a solar year.",s:['q:9:36']},
  {q:"Which major event began during the month of Ramadan?",c:["The revelation of the Qur'an","The building of the Kaaba","The Hijrah to Medina","The Battle of Uhud"],b:0,e:"The Qur'an began to be revealed during Ramadan.",s:['q:2:185']},
  {q:"How many months are there in the Muslim (Hijri) year?",c:["12","10","13","11"],b:0,e:"The Hijri year has 12 lunar months.",s:['q:9:36']},
  {q:"According to the hadith, what sign marks the start of the Ramadan fast?",c:["Seeing the new crescent moon","Seeing the full moon","The 15th of Sha'ban, every year","The first Friday after Sha'ban"],b:0,e:"“Fast when you see it”: this refers to the crescent moon.",s:['h:croissant']},
  {q:"What is the name of the month after Ramadan, whose 1st day is Eid al-Fitr?",c:["Shawwal","Sha'ban","Rajab","Muharram"],b:0,e:"The 1st of Shawwal is the day of Eid al-Fitr.",s:['f:mois']},
  {q:"Which month of the Muslim calendar comes right before Ramadan?",c:["Sha'ban","Shawwal","Dhul-Hijjah","Safar"],b:0,e:"Sha'ban is the 8th month, just before Ramadan.",s:['f:mois']},
  {q:"In which year of the Hijrah did fasting in Ramadan become obligatory?",c:["Year 2","Year 1","Year 10","Year 8"],b:0,e:"Fasting in Ramadan was prescribed in Medina, in year 2 of the Hijrah.",s:['f:jeune2']},
  {q:"How many days can the month of Ramadan last?",c:["29 or 30 days","Always 30 days","28 days","31 days"],b:0,e:"A lunar month lasts 29 or 30 days, depending on when the next crescent appears.",s:['h:croissant']}
 ]},
'r-jeuner':{titre:"Who must fast?",
 texte:["Fasting in Ramadan is obligatory for every Muslim who has reached puberty, is of sound mind and is able to fast.",
  "Someone who is ill or travelling may skip the fast and make up the days later. A woman who is on her period does not fast and makes up the days afterwards.",
  "A person who will never be able to fast, such as a very elderly person, feeds one poor person for each missed day: this is the fidya."],
 retenir:"Allowances exist: Allah wants ease for us.",
 sources:['q:2:184','q:2:185'],
 quiz:[
  {q:"During Ramadan, what should a traveller do about the days they did not fast?",c:["Make up those days later","Nothing at all","Pay a fine","Fast twice as many days"],b:0,e:"They make up the same number of days after Ramadan.",s:['q:2:184']},
  {q:"What is the compensation of feeding one poor person for each missed day of fasting called?",c:["The fidya","Sadaqah","Zakat al-fitr","The kaffara"],b:0,e:"The fidya mainly concerns those who will never be able to make up the days, such as very elderly people.",s:['q:2:184']},
  {q:"Is fasting in Ramadan obligatory for a child who has not reached puberty?",c:["No, but they can be gently trained to fast","Yes, from the age of 7","Yes, but only on Fridays","Only during the last ten days"],b:0,e:"It is not obligatory. Yet the Companions used to train their children to fast, for example on the day of Ashura.",s:['h:enfants']},
  {q:"During Ramadan, what does a woman do when she is on her period?",c:["She does not fast and makes up the days afterwards","She fasts anyway","She never makes up the days","She fasts for half the day"],b:0,e:"She does not fast, then makes up the missed days after Ramadan.",s:['h:regles']},
  {q:"Does a sick person who does not fast in Ramadan have to make up the missed days?",c:["Yes, when they are able to","No, never","Yes, but twice as many","No, they always pay a fine"],b:0,e:"They make up the same number of days once they are able to.",s:['q:2:184']},
  {q:"Does a woman have to make up the prayers she did not perform during her period?",c:["No, she only makes up the fasting","Yes, all the prayers","Yes, half of the prayers","Only the Friday prayer"],b:0,e:"She makes up the fasting, but not the prayers.",s:['h:regles']},
  {q:"According to the verse about fasting, what does Allah want for the believers?",c:["Ease","Hardship","Tiredness","Wealth"],b:0,e:"“Allah intends ease for you and does not intend hardship for you.”",s:['q:2:185']},
  {q:"What does a very elderly person who will never be able to fast again do?",c:["They feed one poor person for each day","They fast anyway","They have nothing to do","They make up the days after the next Ramadan"],b:0,e:"This is the fidya: one meal for a poor person for each day not fasted.",s:['q:2:184']},
  {q:"Who is obliged to fast in Ramadan?",c:["A Muslim who has reached puberty, is of sound mind and is able to fast","All children","Only men","Only those who have done the Hajj"],b:0,e:"These are the conditions set out by the scholars.",s:['f:conditions']},
  {q:"According to the Qur'an, was fasting prescribed before the Muslims?",c:["Yes, to those who came before them","No, never","Only to the people of Mecca","Only to the people of Nuh"],b:0,e:"“Fasting has been prescribed for you as it was prescribed for those before you.”",s:['q:2:183']}
 ]},
'r-rompt':{titre:"What breaks the fast",
 texte:["The fast begins at dawn, at the time of the Fajr prayer, and ends at sunset, at the time of the Maghrib prayer.",
  "Deliberately eating, drinking or having intimate relations during the day breaks the fast.",
  "Someone who eats or drinks out of forgetfulness carries on fasting: their fast is still valid."],
 retenir:"Eating or drinking out of forgetfulness does not break the fast.",
 sources:['q:2:187','h:oubli'],
 quiz:[
  {q:"At what time of day does the Ramadan fast begin?",c:["At dawn (Fajr)","At midnight","At sunrise","At noon"],b:0,e:"The fast begins at dawn, when the white thread becomes distinct from the black thread.",s:['q:2:187']},
  {q:"When is the Ramadan fast broken?",c:["At sunset (Maghrib)","When night is fully dark (Isha)","At 4 p.m.","In the middle of the night"],b:0,e:"The fast is broken as soon as the sun has set.",s:['h:coucher']},
  {q:"A fasting person drinks water, having forgotten they were fasting. What happens to their fast?",c:["It is still valid","It is cancelled","They must fast it twice","It depends on how much they drank"],b:0,e:"They complete their fast: it is Allah who fed them and gave them drink.",s:['h:oubli']},
  {q:"What happens if a fasting person deliberately eats in the middle of a Ramadan day?",c:["Their fast is broken","Nothing changes","It is allowed if they are in the mosque","It is allowed after the Dhuhr prayer"],b:0,e:"Deliberately eating during the day breaks the fast.",s:['q:2:187']},
  {q:"According to the Qur'an, until when may you eat and drink during the nights of Ramadan?",c:["Until the white thread of dawn becomes distinct from the black thread of night","Until midnight","Until sunrise","Until the Isha prayer"],b:0,e:"This is the image used in verse 187 of Surah Al-Baqarah.",s:['q:2:187']},
  {q:"In the verse about fasting, what does “the white thread” stand for?",c:["The light of dawn","A real woollen thread","The crescent moon","The first evening star"],b:0,e:"The white thread is the light of dawn, the black thread the darkness of night.",s:['q:2:187']},
  {q:"During Ramadan, is it allowed to eat and drink at night, after sunset?",c:["Yes, until dawn","No, never during the whole month","Only water","Only after the tarawih prayer"],b:0,e:"The fast only covers the daytime, from dawn to sunset.",s:['q:2:187']},
  {q:"According to the hadith, who “fed and gave drink” to someone who eats or drinks out of forgetfulness while fasting?",c:["Allah","Their family","An angel","No one"],b:0,e:"Their fast is still valid: it is Allah who fed them and gave them drink.",s:['h:oubli']},
  {q:"During the days of Ramadan, are intimate relations between spouses allowed?",c:["No, they break the fast","Yes, at any time","Yes, in the afternoon","Only on the day of Ashura"],b:0,e:"Verse 187 allows them during the nights of Ramadan; during the day, they break the fast.",s:['q:2:187']},
  {q:"Which prayer marks the end of the fasting day?",c:["The Maghrib prayer","The Fajr prayer","The Dhuhr prayer","The Isha prayer"],b:0,e:"Maghrib is the sunset prayer, the time to break the fast.",s:['h:coucher']}
 ]},
'r-suhur':{titre:"Suhur and iftar",
 texte:["Suhur is the meal eaten before dawn. The Prophet ﷺ encouraged people to eat it, because there is a blessing in it.",
  "Iftar is the breaking of the fast at sunset. It is recommended not to delay it.",
  "The sunnah is to break the fast with fresh dates, or if there are none, dried dates, or if there are none, a few sips of water."],
 retenir:"Suhur before dawn. Iftar as soon as the sun sets, with dates.",
 sources:['h:suhur','h:dattes'],
 quiz:[
  {q:"What is the meal eaten before dawn during Ramadan called?",c:["Suhur","Iftar","Walima","Aqiqah"],b:0,e:"Suhur is the meal at the end of the night, before Fajr.",s:['h:suhur']},
  {q:"According to the hadith, what does the suhur meal contain?",c:["A blessing","An obligation","Nothing special","A trial"],b:0,e:"“Eat suhur, for in suhur there is a blessing.”",s:['h:suhur']},
  {q:"What did the Prophet ﷺ prefer to break his fast with?",c:["Dates","Camel's milk","Harira soup","Bread"],b:0,e:"Fresh dates, or else dried dates, or else a few sips of water.",s:['h:dattes']},
  {q:"Should you delay breaking the fast (iftar) after sunset?",c:["No, it is recommended to hasten it","Yes, by one hour","Yes, until Isha","It does not matter at all"],b:0,e:"It is recommended to break the fast as soon as the sun has set.",s:['h:hater']},
  {q:"What is the meal that breaks the fast at sunset called?",c:["Iftar","Suhur","Ghusl","Dhikr"],b:0,e:"Iftar is the breaking of the fast.",s:['h:hater']},
  {q:"When there were no dates, what did the Prophet ﷺ break his fast with?",c:["A few sips of water","Honey","Goat's milk","Figs"],b:0,e:"Fresh dates, or else dried ones, or else a few sips of water.",s:['h:dattes']},
  {q:"Did the Prophet ﷺ break his fast before or after the Maghrib prayer?",c:["Before praying","After praying","The next day","After the Isha prayer"],b:0,e:"He broke his fast before praying, with a few dates.",s:['h:dattes']},
  {q:"According to the hadith, as long as people hasten to break the fast, they will remain…",c:["In goodness","In doubt","In danger","Without reward"],b:0,e:"“People will remain in goodness as long as they hasten to break the fast.”",s:['h:hater']},
  {q:"Is suhur required for the fast to be valid?",c:["No, but it is strongly recommended","Yes, otherwise the fast is cancelled","Yes, only on the first day","It is forbidden"],b:0,e:"It is a sunnah: the Prophet ﷺ encouraged it for its blessing.",s:['h:suhur']},
  {q:"Which kind of dates did the Prophet ﷺ prefer for breaking the fast?",c:["Fresh dates (rutab)","Dried dates (tamr)","Dried figs","Raisins"],b:0,e:"He began with fresh dates; if there were none, dried dates.",s:['h:dattes']}
 ]},
'r-merites':{titre:"The virtues of fasting",
 texte:["Allah prescribed fasting so that the believer may reach piety (taqwa): being mindful of Allah in every action.",
  "The Prophet ﷺ promised forgiveness of past sins to whoever fasts Ramadan with faith and hoping for Allah's reward.",
  "At the end of the month, every Muslim gives zakat al-fitr before the Eid prayer. It purifies the fasting person and feeds the poor."],
 retenir:"Fasting leads to piety. Zakat al-fitr is given before the Eid prayer.",
 sources:['q:2:183','h:pardon','h:fitr'],
 quiz:[
  {q:"According to the Qur'an, for what purpose did Allah prescribe fasting?",c:["To reach piety (taqwa)","Only to purify the body","To commemorate the Hijrah","To replace zakat"],b:0,e:"The verse that prescribes fasting ends with the hope of reaching piety.",s:['q:2:183']},
  {q:"According to the hadith, what does someone gain who fasts Ramadan with faith and hoping for Allah's reward?",c:["Their past sins are forgiven","They no longer need to pray","They are exempt from zakat","Nothing special"],b:0,e:"Their past sins are forgiven.",s:['h:pardon']},
  {q:"When must zakat al-fitr be given?",c:["Before the Eid al-Fitr prayer","One month after Ramadan","Only at the start of Ramadan","Any time during the year"],b:0,e:"The Prophet ﷺ ordered that it be given before people go out to the Eid prayer.",s:['h:fitr']},
  {q:"What does the word “taqwa” mean?",c:["Piety, mindfulness of Allah","Patience (sabr)","Gratitude (shukr)","Repentance (tawbah)"],b:0,e:"Taqwa is the reverent awe of Allah that drives a person towards good.",s:['q:2:183']},
  {q:"Who must give zakat al-fitr?",c:["Every Muslim, young or old, male or female","Only the rich","Only men","Only those who fasted the whole month"],b:0,e:"The hadith prescribes it for every Muslim; the head of the family gives it on behalf of their household.",s:['h:fitr']},
  {q:"What quantity of food does the hadith set for zakat al-fitr?",c:["One sa'","One mithqal of gold","One mudd of wheat","One silver dirham"],b:0,e:"A sa' is a measure of about four double handfuls.",s:['h:fitr']},
  {q:"Which foods are mentioned in the hadith on zakat al-fitr narrated by Ibn Umar?",c:["Dates or barley","Rice or couscous","Meat or fish","Milk or honey"],b:0,e:"One sa' of dates or one sa' of barley.",s:['h:fitr']},
  {q:"According to the hadith, under what conditions does fasting Ramadan wipe out past sins?",c:["With faith and hope of Allah's reward","By fasting in silence","By fasting for 40 days","With no conditions at all"],b:0,e:"You must fast with faith and hoping for Allah's reward.",s:['h:pardon']},
  {q:"What is the purpose of zakat al-fitr, according to the hadith of Ibn Abbas?",c:["To purify the fasting person and feed the poor","To fund the building of mosques","To replace the fast of the sick","To reward the tarawih imam"],b:0,e:"It purifies the fasting person of idle talk and feeds the poor.",s:['h:fitr_but']},
  {q:"With which call does the verse prescribing the Ramadan fast begin?",c:["“O you who believe!”","“O people!”","“O Prophet!”","“O children of Adam!”"],b:0,e:"Verse 183 of Surah Al-Baqarah begins with “O you who believe!”.",s:['q:2:183']}
 ]},
'r-nuits':{titre:"The nights of Ramadan",
 texte:["The nights of Ramadan are a chance to pray more. Their night prayer is called tarawih. The Prophet ﷺ promised forgiveness to whoever prays during the nights of Ramadan with faith and hope of reward.",
  "During the last ten nights, he would strive even harder: he stayed up at night in prayer and woke his family.",
  "He also performed i'tikaf: a spiritual retreat in the mosque during the last ten days, and he did so until the end of his life."],
 retenir:"Tarawih, the last ten nights, i'tikaf: the nights of Ramadan are lived in prayer.",
 sources:['h:qiyam','h:dixnuits','h:itikaf'],
 quiz:[
  {q:"What is the night prayer performed during Ramadan called?",c:["Tarawih","The Duha prayer","The istikharah prayer","The funeral prayer"],b:0,e:"Tarawih is the prayer of the nights of Ramadan.",s:['h:qiyam']},
  {q:"According to the hadith, what does someone gain who prays during the nights of Ramadan with faith and hope of reward?",c:["Their past sins are forgiven","A place in the front row of the mosque","They no longer have to fast","Nothing special"],b:0,e:"Their past sins are forgiven.",s:['h:qiyam']},
  {q:"What is i'tikaf?",c:["A spiritual retreat in the mosque","A journey to Mecca","The fast of Ashura","A type of charity"],b:0,e:"You stay in the mosque to devote yourself to worship.",s:['h:itikaf']},
  {q:"During which part of Ramadan did the Prophet ﷺ perform i'tikaf?",c:["The last ten days","The first ten days","Only the first day","After Eid"],b:0,e:"He performed it during the last ten days of Ramadan.",s:['h:itikaf']},
  {q:"What did the Prophet ﷺ do during the last ten nights of Ramadan?",c:["He stayed up in prayer and woke his family","He travelled","He went to bed earlier","He stopped fasting"],b:0,e:"He strove even harder in worship.",s:['h:dixnuits']},
  {q:"Did the Prophet ﷺ keep performing i'tikaf until the end of his life?",c:["Yes, until his death","No, only once","No, never","Only in Mecca"],b:0,e:"Aisha reports that he practised it until Allah took him back to Him.",s:['h:itikaf']},
  {q:"Where is i'tikaf performed?",c:["In the mosque","At home","In the cave of Hira","In the cemetery"],b:0,e:"The Qur'an mentions those who are in retreat in the mosques.",s:['q:2:187']},
  {q:"Which very important night falls among the last ten nights of Ramadan?",c:["Laylat al-Qadr, the Night of Decree","The night of the Hijrah","The night of Eid al-Adha","The night of the Mawlid"],b:0,e:"It should be sought in the odd nights of the last ten nights.",s:['h:qadr']},
  {q:"Is the tarawih prayer obligatory?",c:["No, it is a highly recommended voluntary prayer","Yes, like the five prayers","Yes, but only in the mosque","It is forbidden"],b:0,e:"The Prophet ﷺ prayed it in congregation for a few nights, then stopped for fear it would become obligatory.",s:['h:tarawih']},
  {q:"Why did the Prophet ﷺ stop leading tarawih in congregation after a few nights?",c:["For fear it would become obligatory","Because he was ill","Because the mosque was too small","Because Ramadan was over"],b:0,e:"He feared it would be made obligatory for his community.",s:['h:tarawih']}
 ]},
'r-qadr':{titre:"Laylat al-Qadr, the Night of Decree",
 texte:["Laylat al-Qadr, the Night of Decree, is the night when the revelation of the Qur'an began.",
  "Allah says it is “better than a thousand months”. The angels descend during it, and it is peace until dawn. A whole surah is devoted to it: Surah Al-Qadr (97).",
  "It is sought in the last ten nights of Ramadan, especially the odd nights, by praying and making du'a more than usual."],
 retenir:"Better than a thousand months. Seek it in the odd nights of the last ten nights.",
 sources:['q:97:1','q:97:3','h:qadr'],
 quiz:[
  {q:"According to the Qur'an, the Night of Decree (Laylat al-Qadr) is better than how long?",c:["A thousand months","A hundred days","One year","Ten nights"],b:0,e:"It is better than a thousand months, which is more than 83 years.",s:['q:97:3']},
  {q:"Which surah of the Qur'an is devoted to the Night of Decree (Laylat al-Qadr)?",c:["Al-Qadr","Al-Fatiha","Al-Ikhlas","Ya-Sin"],b:0,e:"Surah 97, Al-Qadr, is named after this night.",s:['q:97:1']},
  {q:"In which nights of Ramadan should you mainly look for the Night of Decree (Laylat al-Qadr)?",c:["The odd nights of the last ten nights","The first ten nights","The first night","The night of Eid"],b:0,e:"The odd nights of the last ten: the 21st, 23rd, 25th, 27th and 29th.",s:['h:qadr']},
  {q:"What event took place on the Night of Decree (Laylat al-Qadr)?",c:["The beginning of the revelation of the Qur'an","The Hijrah to Medina","The birth of the Prophet ﷺ","The first pilgrimage"],b:0,e:"The revelation of the Qur'an began during this night.",s:['q:97:1']},
  {q:"According to Surah Al-Qadr, who descends during the Night of Decree?",c:["The angels and the Spirit (Jibril)","The prophets","The jinn","No one"],b:0,e:"The angels and the Spirit descend in it, by the permission of their Lord.",s:['q:97:4']},
  {q:"According to Surah Al-Qadr, until when is the Night of Decree peace?",c:["Until the break of dawn","Until midnight","Until the end of Ramadan","Until Eid"],b:0,e:"“Peace it is until the emergence of dawn.”",s:['q:97:5']},
  {q:"How many verses does Surah Al-Qadr have?",c:["5","7","3","10"],b:0,e:"Surah Al-Qadr has 5 verses.",s:['q:97:5']},
  {q:"A thousand months is roughly how many years?",c:["More than 83 years","10 years","40 years","1,000 years"],b:0,e:"1,000 months ÷ 12 ≈ 83 years and 4 months: more than a whole lifetime.",s:['q:97:3']},
  {q:"Which are the odd nights among the last ten nights of Ramadan?",c:["The 21st, 23rd, 25th, 27th and 29th","The 20th, 22nd, 24th, 26th and 28th","The 1st, 3rd, 5th, 7th and 9th","The 11th, 13th, 15th, 17th and 19th"],b:0,e:"These are the nights recommended for seeking Laylat al-Qadr.",s:['h:qadr']},
  {q:"Which du'a did the Prophet ﷺ teach Aisha for the Night of Decree?",c:["“Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî”","“Bismi Llâh”","“Allâhu akbar”","“Subḥâna Llâh”"],b:0,e:"“O Allah, You are the One who pardons, You love to pardon, so pardon me.”",s:['h:afw']}
 ]},
'r-aid':{titre:"Eid al-Fitr",
 texte:["Eid al-Fitr is the festival of breaking the fast. It takes place on the 1st day of the month of Shawwal, right after Ramadan.",
  "Before going out to the Eid prayer, the Prophet ﷺ would eat a few dates, an odd number of them. Zakat al-fitr must be given before this prayer.",
  "After Eid, it is recommended to fast six days of the month of Shawwal: together with Ramadan, it is like fasting the whole year."],
 retenir:"1st of Shawwal: Eid. Dates before the prayer, then six days of Shawwal.",
 sources:['h:aid_dattes','h:shawwal','q:2:185'],
 quiz:[
  {q:"On which day does Eid al-Fitr take place?",c:["The 1st day of Shawwal","The 27th of Ramadan","The 10th of Dhul-Hijjah","The 1st of Muharram"],b:0,e:"Eid al-Fitr comes straight after the month of Ramadan.",s:['f:mois']},
  {q:"What does “Eid al-Fitr” mean?",c:["The festival of breaking the fast","The festival of sacrifice","The festival of the Hijrah","The festival of the Prophet's ﷺ birth"],b:0,e:"Fitr means breaking the fast.",s:['f:aid']},
  {q:"What did the Prophet ﷺ eat before going out to the Eid al-Fitr prayer?",c:["A few dates","Figs","Meat","Nothing, he was fasting"],b:0,e:"He would not go out on the day of Eid al-Fitr without first eating a few dates.",s:['h:aid_dattes']},
  {q:"How many dates did the Prophet ﷺ eat on the morning of Eid al-Fitr?",c:["An odd number","Always two","Always seven","An even number"],b:0,e:"Anas reports that he ate them in an odd number.",s:['h:aid_dattes']},
  {q:"How many Eid festivals does Islam have in a year?",c:["2","1","3","5"],b:0,e:"Eid al-Fitr and Eid al-Adha.",s:['f:aid']},
  {q:"According to the hadith, how many days of Shawwal is it recommended to fast after Ramadan?",c:["6","3","10","30"],b:0,e:"Six days of Shawwal, in a row or not.",s:['h:shawwal']},
  {q:"According to the hadith, fasting Ramadan and then six days of Shawwal is equal to what?",c:["Fasting the whole year","Performing the Hajj","Fasting one more month","Nothing special"],b:0,e:"It is as if one had fasted the whole year.",s:['h:shawwal']},
  {q:"Before which prayer must zakat al-fitr have been given?",c:["The Eid prayer","The Friday prayer","The Maghrib prayer","Tarawih"],b:0,e:"It must be given before people go out to the Eid prayer.",s:['h:fitr']},
  {q:"According to verse 185 of Surah Al-Baqarah, what do the believers do once they have completed the number of days of Ramadan?",c:["They proclaim the greatness of Allah","They start fasting again","They perform i'tikaf","They set off to visit Medina"],b:0,e:"The verse invites us to proclaim Allah's greatness for the guidance received: this is the takbir of Eid.",s:['q:2:185']},
  {q:"What is the other major festival of Islam, celebrated during the pilgrimage?",c:["Eid al-Adha","Eid al-Fitr","The Mawlid","The 1st of Muharram"],b:0,e:"Eid al-Adha, the festival of sacrifice, takes place on the 10th of Dhul-Hijjah.",s:['f:aid']}
 ]},

/* ===================== PILLARS & PRAYER ===================== */
'p-piliers':{titre:"The five pillars of Islam",
 texte:["Islam is built on five pillars, listed in an authentic hadith narrated by al-Bukhari and Muslim.",
  "The shahada, the declaration of faith. Salah, the five daily prayers. Zakat, the obligatory charity. Hajj, the pilgrimage to Mecca for those who can afford it. Sawm, fasting in Ramadan.",
  "These five pillars are the foundations of a Muslim's practice, all year round."],
 retenir:"Shahada, salah, zakat, Hajj, fasting in Ramadan.",
 sources:['h:piliers'],
 quiz:[
  {q:"How many pillars does Islam have?",c:["5","3","4","6"],b:0,e:"Islam is built on five pillars.",s:['h:piliers']},
  {q:"What is fasting called in Arabic?",c:["Sawm (or siyam)","Salah","Zakat","Hajj"],b:0,e:"Fasting is called sawm or siyam; it is the word used in the verse that prescribes it.",s:['q:2:183']},
  {q:"For whom is the pilgrimage to Mecca (Hajj) obligatory?",c:["For those who can afford it, once in a lifetime","For everyone, every year","Only for men","Only during Ramadan"],b:0,e:"Hajj is obligatory once in a lifetime for those who are physically and financially able.",s:['q:3:97']},
  {q:"How many obligatory prayers does a Muslim perform each day?",c:["5","3","7","2"],b:0,e:"Fajr, Dhuhr, Asr, Maghrib and Isha.",s:['h:cinq']},
  {q:"What is the first pillar of Islam?",c:["The shahada, the declaration of faith","Fasting","Hajj","Zakat"],b:0,e:"The shahada is mentioned first in the hadith.",s:['h:piliers']},
  {q:"Which pillar of Islam is the obligatory charity?",c:["Zakat","Salah","Sawm","Shahada"],b:0,e:"Zakat is paid every year on wealth that reaches a minimum threshold.",s:['h:piliers']},
  {q:"Which pillar of Islam is practised during the month of Ramadan?",c:["Fasting (sawm)","Hajj","Zakat","Shahada"],b:0,e:"Fasting in Ramadan is one of the five pillars.",s:['h:piliers']},
  {q:"Which pillar of Islam involves travelling to Mecca?",c:["Hajj","Salah","Sawm","Zakat"],b:0,e:"Hajj is the pilgrimage to the Sacred House.",s:['q:3:97']},
  {q:"According to the hadith, how many times in a lifetime is Hajj obligatory?",c:["Only once","Every year","Three times","Seven times"],b:0,e:"The Prophet ﷺ made clear that it was not obligatory every year.",s:['h:hajj_une']},
  {q:"Which Companion narrated the hadith of the five pillars of Islam?",c:["Abdullah ibn Umar","Abu Bakr","Bilal","Khalid ibn al-Walid"],b:0,e:"The hadith is narrated by Ibn Umar.",s:['h:piliers']}
 ]},
'p-shahada':{titre:"The shahada, the declaration of faith",
 texte:["The shahada is the declaration of faith: “Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh”.",
  "It means: “I bear witness that there is no god but Allah, and I bear witness that Muhammad is the Messenger of Allah.”",
  "It is the first pillar: through it, a person enters Islam. It affirms the oneness of Allah, tawhid, which is summed up in Surah Al-Ikhlas."],
 retenir:"Lâ ilâha illâ Llâh, Muḥammadun rasûlu Llâh.",
 sources:['q:47:19','q:48:29','h:piliers'],
 quiz:[
  {q:"Which pillar of Islam is the declaration of faith?",c:["The shahada","Salah","Zakat","Hajj"],b:0,e:"The shahada is the first pillar.",s:['h:piliers']},
  {q:"What does “lâ ilâha illâ Llâh” mean?",c:["There is no god but Allah","Allah is the Greatest","Glory be to Allah","In the name of Allah"],b:0,e:"This is the first part of the shahada.",s:['q:47:19']},
  {q:"What does “Muḥammadun rasûlu Llâh” mean?",c:["Muhammad is the Messenger of Allah","Muhammad is an angel","Muhammad is the first man","Muhammad is a king"],b:0,e:"This is the second part of the shahada.",s:['q:48:29']},
  {q:"What is the belief in the oneness of Allah called?",c:["Tawhid","Hajj","Sunnah","Fiqh"],b:0,e:"Tawhid is the heart of the Muslim faith.",s:['q:112:1']},
  {q:"Which surah sums up the oneness of Allah in four verses?",c:["Al-Ikhlas","Al-Fatiha","Al-Kawthar","An-Nas"],b:0,e:"Surah 112, Al-Ikhlas.",s:['q:112:1']},
  {q:"How many parts does the shahada have?",c:["Two: the oneness of Allah and the message of Muhammad ﷺ","Only one","Five","Seven"],b:0,e:"You bear witness to the oneness of Allah, then that Muhammad ﷺ is His Messenger.",s:['h:piliers']},
  {q:"According to Surah Al-Ikhlas, did Allah beget or was He begotten?",c:["Neither","Both","He begot","He was begotten"],b:0,e:"“He neither begets nor is born.”",s:['q:112:3']},
  {q:"What does “Ash-hadu” at the start of the shahada mean?",c:["I bear witness","I pray","I fast","I forgive"],b:0,e:"Ash-hadu means “I bear witness, I testify”.",s:['f:shahada']},
  {q:"What does a person do to enter Islam?",c:["They say the shahada with conviction","They fast for a month","They perform Hajj","They learn Arabic"],b:0,e:"Saying the shahada sincerely brings a person into Islam.",s:['f:shahada']},
  {q:"What does the Qur'an say about Muhammad ﷺ in Surah Al Imran, verse 144?",c:["He is only a messenger; other messengers passed away before him","He is eternal","He is an angel","He is the first prophet"],b:0,e:"Muhammad ﷺ is a human being and a messenger, like those who came before him.",s:['q:3:144']}
 ]},
'p-priere':{titre:"Prayer, five appointments a day",
 texte:["A Muslim prays five times a day: Fajr at dawn, Dhuhr at midday, Asr in the afternoon, Maghrib at sunset and Isha at night.",
  "Each prayer has a set number of units (rak'ahs): 2 for Fajr, 4 for Dhuhr, 4 for Asr, 3 for Maghrib and 4 for Isha.",
  "You pray facing the Kaaba, in Mecca: this direction is the qiblah. The time of each prayer is announced by the adhan. On Fridays, the Dhuhr prayer is replaced by the Friday prayer (Jumu'ah)."],
 retenir:"Fajr 2, Dhuhr 4, Asr 4, Maghrib 3, Isha 4 — facing the qiblah.",
 sources:['q:4:103','f:rakat','q:2:144'],
 quiz:[
  {q:"How many units (rak'ahs) does the obligatory Fajr prayer have?",c:["2","3","4","1"],b:0,e:"The Fajr prayer has 2 rak'ahs.",s:['f:rakat']},
  {q:"How many units (rak'ahs) does the obligatory Maghrib prayer have?",c:["3","2","4","5"],b:0,e:"Maghrib is the only obligatory prayer with 3 rak'ahs.",s:['f:rakat']},
  {q:"Which direction do Muslims face when they pray?",c:["Towards the Kaaba, in Mecca","Towards Jerusalem","Towards Medina","Towards the east"],b:0,e:"This direction is called the qiblah.",s:['q:2:144']},
  {q:"What is the call that announces the time of prayer called?",c:["The adhan","The iqamah","Du'a","Dhikr"],b:0,e:"The adhan announces the time; the iqamah announces the start of the congregational prayer.",s:['h:adhan']},
  {q:"What is the obligatory prayer performed at dawn called?",c:["Fajr","Dhuhr","Asr","Isha"],b:0,e:"Fajr is prayed between dawn and sunrise.",s:['f:rakat']},
  {q:"How many units (rak'ahs) does the obligatory Dhuhr prayer have?",c:["4","2","3","5"],b:0,e:"Dhuhr has 4 rak'ahs.",s:['f:rakat']},
  {q:"How many obligatory units (rak'ahs) are there in total in the five prayers of a day?",c:["17","15","20","12"],b:0,e:"2 + 4 + 4 + 3 + 4 = 17 rak'ahs.",s:['f:rakat']},
  {q:"According to the Qur'an, how has prayer been prescribed for the believers?",c:["At set times","Once a week","Whenever you like","Only during Ramadan"],b:0,e:"“Indeed, prayer has been decreed upon the believers at specified times.”",s:['q:4:103']},
  {q:"Which congregational prayer takes place every Friday instead of Dhuhr?",c:["The Friday prayer (Jumu'ah)","The Eid prayer","Tarawih","The prayer for rain"],b:0,e:"The Qur'an calls believers to hasten to the remembrance of Allah on Friday.",s:['q:62:9']},
  {q:"According to the hadith, during which event were the five prayers prescribed?",c:["The Night Journey (al-Isra' wal-Mi'raj)","The Battle of Badr","The Hijrah","The conquest of Mecca"],b:0,e:"Fifty prayers were prescribed, then reduced to five.",s:['h:cinq']}
 ]},
'p-ablutions':{titre:"Ablution and Al-Fatiha",
 texte:["Before praying, a Muslim purifies themselves with water: this is ablution (wudu). If there is no water, you perform tayammum with clean earth.",
  "You wash your face, your hands and forearms up to the elbows, wipe your wet hands over your head, then wash your feet up to the ankles.",
  "In every unit of prayer, you recite Surah Al-Fatiha, “the Opening”, the first surah of the Qur'an, which has 7 verses."],
 retenir:"No prayer without ablution, no prayer without Al-Fatiha.",
 sources:['q:5:6','q:1:2','h:fatiha'],
 quiz:[
  {q:"What is the purification with water performed before prayer called?",c:["Ablution (wudu)","Fasting","Zakat","I'tikaf"],b:0,e:"Wudu purifies you before prayer.",s:['q:5:6']},
  {q:"Which surah is recited in every unit (rak'ah) of prayer?",c:["Al-Fatiha","Al-Ikhlas","Al-Baqarah","Ya-Sin"],b:0,e:"Al-Fatiha, “the Opening”, is recited in every rak'ah.",s:['h:fatiha']},
  {q:"With which phrase does Surah Al-Fatiha begin?",c:["Bismi Llâhi r-Raḥmâni r-Raḥîm","Qul huwa Llâhu aḥad","Allâhu akbar","Subḥâna Llâh"],b:0,e:"“In the name of Allah, the Entirely Merciful, the Especially Merciful.”",s:['q:1:1']},
  {q:"According to the Qur'an, up to where are the arms washed during ablution?",c:["Up to the elbows","Up to the wrists","Up to the shoulders","Only the fingers"],b:0,e:"Verse 6 of Surah Al-Ma'idah states this.",s:['q:5:6']},
  {q:"According to the Qur'an, what do you do to your head during ablution?",c:["You wipe your wet hands over it","You wash it completely three times","You cover it with a turban","You pour water on the back of your neck"],b:0,e:"This is the mash: wiping your wet hands over your head.",s:['q:5:6']},
  {q:"What do you do when you cannot find water to purify yourself before prayer?",c:["Tayammum, with clean earth","You do not pray","You wait until the next day","You pray without purification"],b:0,e:"The same verse provides for tayammum when there is no water.",s:['q:5:6']},
  {q:"According to the hadith, does Allah accept the prayer of someone who has lost their ablution without renewing it?",c:["No, not until they renew their ablution","Yes, always","Yes, on Fridays","Only the Fajr prayer"],b:0,e:"The prayer is only accepted after renewing one's ablution.",s:['h:wudu']},
  {q:"How many verses does Surah Al-Fatiha have?",c:["7","5","10","3"],b:0,e:"It is called “the seven oft-repeated verses”.",s:['q:15:87']},
  {q:"What does “Al-ḥamdu li-Llâhi rabbi l-ʿâlamîn” mean?",c:["Praise be to Allah, Lord of the worlds","Allah is the Greatest","There is no god but Allah","I seek refuge with Allah"],b:0,e:"It is the 2nd verse of Al-Fatiha.",s:['q:1:2']},
  {q:"According to the hadith, what is the prayer of someone who does not recite Al-Fatiha worth?",c:["It is not valid","It counts double","It is valid","It counts as half"],b:0,e:"“There is no prayer for the one who does not recite Al-Fatiha.”",s:['h:fatiha']}
 ]},
'p-zakat':{titre:"Zakat, the obligatory charity",
 texte:["Zakat is the obligatory charity, one of the five pillars of Islam. Its name evokes purification and growth: it purifies wealth and helps those most in need.",
  "It is due from anyone whose savings reach a minimum threshold (the nisab) and stay in their possession for a full lunar year. For money, the rate is 2.5%.",
  "The Qur'an lists eight categories of recipients, including the poor and the needy. Sadaqah, on the other hand, is voluntary charity, which can be given at any time."],
 retenir:"Zakat: 2.5% of savings that reach the nisab for a lunar year.",
 sources:['q:9:60','q:9:103','f:zakat'],
 quiz:[
  {q:"Which pillar of Islam is the obligatory charity?",c:["Zakat","Sadaqah","Hajj","Sawm"],b:0,e:"Zakat is obligatory; sadaqah is voluntary.",s:['h:piliers']},
  {q:"What is the rate of zakat on saved money?",c:["2.5%","10%","20%","5%"],b:0,e:"That is one fortieth of the savings.",s:['f:zakat']},
  {q:"What is the minimum threshold of wealth from which zakat is due called?",c:["The nisab","The sa'","The fidya","The hawl"],b:0,e:"Below the nisab, zakat is not obligatory.",s:['f:zakat']},
  {q:"For how long must savings be held for zakat to be due?",c:["One lunar year","One month","Ten years","Only the month of Ramadan"],b:0,e:"This is the hawl: one full lunar year.",s:['f:zakat']},
  {q:"According to the Qur'an, how many categories of people can receive zakat?",c:["8","5","3","12"],b:0,e:"Verse 60 of Surah At-Tawbah lists eight.",s:['q:9:60']},
  {q:"Which of these are among the recipients of zakat mentioned in the Qur'an?",c:["The poor and the needy","The richest people","Shopkeepers","Mosque imams"],b:0,e:"The poor and the needy are mentioned first.",s:['q:9:60']},
  {q:"What is the difference between zakat and sadaqah?",c:["Zakat is obligatory, sadaqah is voluntary","There is none","Sadaqah is obligatory","Zakat is forbidden"],b:0,e:"Sadaqah can be given at any time and in any amount.",s:['f:zakat']},
  {q:"In the Qur'an, which act is zakat very often mentioned together with?",c:["Prayer","Fasting","Pilgrimage","Ablution"],b:0,e:"“And establish prayer and give zakat”: this phrase comes up many times.",s:['q:2:43']},
  {q:"In the order of the hadith of the pillars, where does zakat come?",c:["3rd","1st","5th","2nd"],b:0,e:"Shahada, prayer, zakat, Hajj, fasting in Ramadan.",s:['h:piliers']},
  {q:"What does the word “zakat” evoke in Arabic?",c:["Purification and growth","Patience","Victory","Light"],b:0,e:"The Qur'an says that charity purifies them (tutahhiruhum) and makes them grow in goodness (tuzakkihim).",s:['q:9:103']}
 ]},
'p-hajj':{titre:"Hajj, the pilgrimage",
 texte:["Hajj is the pilgrimage to Mecca, one of the five pillars of Islam. It is obligatory once in a lifetime for those who are physically and financially able.",
  "It takes place during the month of Dhul-Hijjah. The pilgrim enters a state of consecration (ihram), walks seven times around the Kaaba (tawaf) and goes seven times between Safa and Marwa (sa'y). The most important moment is standing at Arafah, on the 9th of Dhul-Hijjah.",
  "The next day, Muslims all over the world celebrate Eid al-Adha, the festival of sacrifice, in memory of Ibrahim."],
 retenir:"Once in a lifetime. Arafah on the 9th of Dhul-Hijjah, Eid al-Adha on the 10th.",
 sources:['q:3:97','q:22:27','h:hajj_pardon'],
 quiz:[
  {q:"In which city is Hajj performed?",c:["Mecca","Medina","Jerusalem","Ta'if"],b:0,e:"Hajj is performed in Mecca and the area around it.",s:['q:3:97']},
  {q:"During which month of the Muslim calendar does Hajj take place?",c:["Dhul-Hijjah","Ramadan","Muharram","Shawwal"],b:0,e:"Hajj takes place from the 8th to the 13th of Dhul-Hijjah.",s:['f:hajj']},
  {q:"According to the hadith, what is the most important part of Hajj?",c:["Standing at Arafah","Praying at al-Aqsa Mosque","Visiting Medina","Visiting the cave of Hira"],b:0,e:"“Hajj is Arafah.”",s:['h:arafa']},
  {q:"Which festival is celebrated the day after the day of Arafah?",c:["Eid al-Adha","Eid al-Fitr","The Mawlid","The 1st of Muharram"],b:0,e:"The 10th of Dhul-Hijjah is Eid al-Adha.",s:['f:hajj']},
  {q:"According to the hadith, how does a pilgrim return who performs Hajj without sin or obscene speech?",c:["As on the day their mother gave birth to them","Richer","Exempt from fasting","With the title of hajji, and no other reward"],b:0,e:"They return cleansed of their sins.",s:['h:hajj_pardon']},
  {q:"Which prophet was commanded to call people to the pilgrimage?",c:["Ibrahim","Musa","Nuh","Yusuf"],b:0,e:"Allah commanded Ibrahim to call people to Hajj.",s:['q:22:27']},
  {q:"What is the state of consecration that the pilgrim enters called?",c:["Ihram","Wudu","I'tikaf","Tayammum"],b:0,e:"Men wear two pieces of unstitched white cloth.",s:['f:hajj']},
  {q:"What are the seven circuits made around the Kaaba called?",c:["Tawaf","Sa'y","A rak'ah","Dhikr"],b:0,e:"Tawaf is done in seven circuits, with the Kaaba on your left.",s:['f:hajj']},
  {q:"Between which two hills does the pilgrim walk seven times?",c:["Safa and Marwa","Arafah and Mina","Uhud and Thawr","Hira and Thawr"],b:0,e:"The Qur'an mentions Safa and Marwa among the symbols of Allah.",s:['q:2:158']},
  {q:"In memory of which prophet do Muslims sacrifice an animal on the day of Eid al-Adha?",c:["Ibrahim","Isa","Musa","Dawud"],b:0,e:"Allah ransomed Ibrahim's son with a great sacrifice.",s:['q:37:107']}
 ]},

/* ===================== QUR'AN ===================== */
'c-coran':{titre:"The Qur'an, the word of Allah",
 texte:["The Qur'an is the word of Allah, revealed in Arabic to the Prophet Muhammad ﷺ through the angel Jibril (Gabriel).",
  "The first revelation took place in the cave of Hira, near Mecca, when the Prophet ﷺ was 40 years old. The first words revealed begin with “Iqra'”: “Read!”.",
  "The revelation lasted about 23 years. The Qur'an has 114 surahs; Allah has promised to preserve it."],
 retenir:"114 surahs, revealed over 23 years. First word: “Iqra'”, “Read!”.",
 sources:['q:96:1','h:hira','q:15:9'],
 quiz:[
  {q:"How many surahs are there in the Qur'an?",c:["114","99","120","30"],b:0,e:"The Qur'an has 114 surahs.",s:['f:coran']},
  {q:"Which angel conveyed the Qur'an to the Prophet Muhammad ﷺ?",c:["Jibril (Gabriel)","Mika'il","Israfil","Malik"],b:0,e:"It was the angel Jibril who conveyed the revelation.",s:['q:2:97']},
  {q:"In which cave did the Prophet ﷺ receive the first revelation of the Qur'an?",c:["The cave of Hira","The cave of Thawr","A cave in Medina","A cave in Jerusalem"],b:0,e:"The cave of Hira is on Jabal an-Nur, near Mecca.",s:['h:hira']},
  {q:"What does “Iqra'”, the first word of the Qur'an to be revealed, mean?",c:["Read!","Pray!","Listen!","Fast!"],b:0,e:"It is the beginning of Surah Al-Alaq (96).",s:['q:96:1']},
  {q:"Over roughly how many years was the Qur'an revealed?",c:["23 years","1 year","40 years","10 years"],b:0,e:"About 13 years in Mecca and 10 years in Medina.",s:['h:vie']},
  {q:"Into how many parts (juz') is the Qur'an divided for reading?",c:["30","114","7","12"],b:0,e:"Thirty parts: for example, one a day during Ramadan.",s:['f:coran']},
  {q:"In which language was the Qur'an revealed?",c:["In Arabic","In Hebrew","In Persian","In Aramaic"],b:0,e:"“Indeed, We have sent it down as an Arabic Qur'an.”",s:['q:12:2']},
  {q:"According to the Qur'an, who guarantees the preservation of the Qur'an?",c:["Allah","Only the scholars","The caliphs","No one"],b:0,e:"“Indeed, it is We who sent down the Qur'an, and indeed, We will be its guardian.”",s:['q:15:9']},
  {q:"How old was the Prophet ﷺ at the time of the first revelation?",c:["40 years old","25 years old","63 years old","13 years old"],b:0,e:"He began to receive the revelation at the age of 40.",s:['h:vie']},
  {q:"What is a verse of the Qur'an called in Arabic?",c:["An ayah","A surah","A juz'","A hadith"],b:0,e:"A verse is called an ayah; a chapter, a surah.",s:['f:coran']}
 ]},
'c-sourates':{titre:"The surahs",
 texte:["The Qur'an is made up of 114 surahs of very different lengths. Each one begins with the basmala, except Surah At-Tawbah.",
  "The first is Al-Fatiha, “the Opening”. The longest is Al-Baqarah, “the Cow”, with 286 verses. The shortest is Al-Kawthar, with 3 verses. The last is An-Nas, “Mankind”.",
  "The surahs revealed before the Hijrah are called Meccan, and those revealed after it are called Medinan."],
 retenir:"First: Al-Fatiha. Longest: Al-Baqarah. Shortest: Al-Kawthar. Last: An-Nas.",
 sources:['q:1:1','q:108:1','q:114:1'],
 quiz:[
  {q:"What is the first surah of the Qur'an?",c:["Al-Fatiha","Al-Baqarah","An-Nas","Al-Alaq"],b:0,e:"Al-Fatiha opens the Qur'an. Al-Alaq contains the first verses revealed, but it is surah 96.",s:['q:1:1']},
  {q:"What is the longest surah of the Qur'an?",c:["Al-Baqarah","Al-Fatiha","Al-Kawthar","Ya-Sin"],b:0,e:"Al-Baqarah, surah 2, has 286 verses.",s:['f:coran']},
  {q:"What is the shortest surah of the Qur'an?",c:["Al-Kawthar","Al-Ikhlas","An-Nas","Al-Asr"],b:0,e:"Al-Kawthar, surah 108, has 3 verses.",s:['q:108:1']},
  {q:"What is the last surah of the Qur'an?",c:["An-Nas","Al-Falaq","Al-Ikhlas","Al-Fatiha"],b:0,e:"An-Nas, “Mankind”, is surah 114.",s:['q:114:1']},
  {q:"Which surah begins with “Qul huwa Llâhu aḥad”?",c:["Al-Ikhlas","An-Nas","Al-Falaq","Al-Kafirun"],b:0,e:"“Say: He is Allah, the One.”",s:['q:112:1']},
  {q:"Which surah contains the verse “This is the Book about which there is no doubt”?",c:["Al-Baqarah","Al-Fatiha","Maryam","Ya-Sin"],b:0,e:"It is the 2nd verse of Surah Al-Baqarah.",s:['q:2:2']},
  {q:"Which surah is named after the mother of Isa (Jesus)?",c:["Maryam","Al Imran","An-Nisa'","Ta-Ha"],b:0,e:"Surah 19 is named after Maryam.",s:['q:19:16']},
  {q:"Which is the only surah that does not begin with “Bismi Llâhi r-Raḥmâni r-Raḥîm”?",c:["At-Tawbah (surah 9)","Al-Fatiha","An-Nas","Al-Baqarah"],b:0,e:"At-Tawbah is the only one of the 114 surahs without the basmala at its start.",s:['f:tawba']},
  {q:"What is the phrase “Bismi Llâhi r-Raḥmâni r-Raḥîm” called?",c:["The basmala","The shahada","The takbir","The talbiyah"],b:0,e:"It means: “In the name of Allah, the Entirely Merciful, the Especially Merciful”.",s:['q:1:1']},
  {q:"What are the surahs revealed in Mecca, before the Hijrah, called?",c:["Meccan surahs","Medinan surahs","Long surahs","Surahs of Ta'if"],b:0,e:"Those revealed after the Hijrah are called Medinan.",s:['f:coran']}
 ]},
'c-ikhlas':{titre:"Al-Ikhlas and the Verse of the Throne",
 texte:["Surah Al-Ikhlas (112) sums up faith in the oneness of Allah: He is One, He neither begets nor was begotten, and there is none equal to Him.",
  "The Prophet ﷺ said that it is equal to a third of the Qur'an.",
  "The Verse of the Throne, Ayat al-Kursi (surah 2, verse 255), is the greatest verse of the Qur'an. It describes the life, knowledge and power of Allah."],
 retenir:"Al-Ikhlas is worth a third of the Qur'an. Ayat al-Kursi is the greatest verse.",
 sources:['q:112:1','h:ikhlas','h:kursi'],
 quiz:[
  {q:"What does “Qul huwa Llâhu aḥad” mean?",c:["Say: He is Allah, the One","In the name of Allah","Allah is the Greatest","Glory be to Allah"],b:0,e:"It is the first verse of Surah Al-Ikhlas.",s:['q:112:1']},
  {q:"According to the hadith, Surah Al-Ikhlas is equal to what portion of the Qur'an?",c:["A third","Half","A tenth","The whole Qur'an"],b:0,e:"The Prophet ﷺ said that it is equal to a third of the Qur'an.",s:['h:ikhlas']},
  {q:"How many verses does Surah Al-Ikhlas have?",c:["4","7","3","5"],b:0,e:"Surah Al-Ikhlas has 4 verses.",s:['q:112:4']},
  {q:"According to Surah Al-Ikhlas, is anyone equal to Allah?",c:["No, there is none equal to Him","Yes, the angels","Yes, the prophets","Yes, the jinn"],b:0,e:"“Nor is there to Him any equivalent.”",s:['q:112:4']},
  {q:"According to the hadith, what is the greatest verse of the Qur'an?",c:["Ayat al-Kursi, the Verse of the Throne","The first verse of Al-Fatiha","The last verse of the Qur'an","The Verse of Light"],b:0,e:"Ubayy ibn Ka'b said so to the Prophet ﷺ, who approved.",s:['h:kursi']},
  {q:"In which surah is Ayat al-Kursi found?",c:["Al-Baqarah, verse 255","Al-Fatiha, verse 1","Ya-Sin, verse 1","Al-Ikhlas, verse 2"],b:0,e:"The Verse of the Throne is the 255th verse of Surah Al-Baqarah.",s:['q:2:255']},
  {q:"According to Ayat al-Kursi, is Allah ever overtaken by drowsiness or sleep?",c:["No, neither drowsiness nor sleep overtakes Him","Yes, at night","Yes, sometimes","Only sleep"],b:0,e:"Allah is the Ever-Living, the Self-Sustaining.",s:['q:2:255']},
  {q:"What does “Allâhu ṣ-ṣamad” mean in Surah Al-Ikhlas?",c:["Allah is the One whom all need, and who needs no one","Allah is the Creator of the sky","Allah is the Forgiver","Allah is the Judge"],b:0,e:"As-Samad is one of the names of Allah.",s:['q:112:2']},
  {q:"What does the name of the surah “Al-Ikhlas” mean?",c:["Pure monotheism, sincerity","The dawn","Victory","Mankind"],b:0,e:"It purifies faith from any association of partners with Allah.",s:['f:ikhlas']},
  {q:"According to Ayat al-Kursi, how much of His knowledge does Allah let His creatures grasp?",c:["Only what He wills","All of His knowledge","Nothing at all","Half of it"],b:0,e:"“And they encompass not a thing of His knowledge except for what He wills.”",s:['q:2:255']}
 ]},

/* ===================== PROPHETS ===================== */
'pr-adam':{titre:"Adam and Nuh",
 texte:["Adam is the first human being and the first prophet. Allah taught him the names of all things, then commanded the angels to prostrate before him. Iblis refused out of arrogance.",
  "Nuh (Noah) called his people to worship Allah alone for 950 years. Few people followed him, not even his own son.",
  "At Allah's command, Nuh built the ark, which saved him from the flood together with the believers and pairs of animals."],
 retenir:"Adam, the first human. Nuh, 950 years of preaching, and the ark.",
 sources:['q:2:31','q:2:34','q:29:14'],
 quiz:[
  {q:"Who is the first prophet of humankind?",c:["Adam","Nuh (Noah)","Ibrahim (Abraham)","Musa (Moses)"],b:0,e:"Adam is the first human being and the first prophet.",s:['q:2:31']},
  {q:"What did Allah teach Adam?",c:["The names of all things","The whole Qur'an by heart","Only the language of the angels","Only the names of the prophets"],b:0,e:"“And He taught Adam the names, all of them.”",s:['q:2:31']},
  {q:"Who refused to prostrate before Adam?",c:["Iblis","Jibril","Mika'il","All the angels"],b:0,e:"The angels prostrated, except Iblis.",s:['q:2:34']},
  {q:"Why did Iblis refuse to prostrate before Adam?",c:["Out of arrogance","Out of forgetfulness","Out of fear","Because he had not heard the command"],b:0,e:"He refused, was arrogant and became one of the disbelievers.",s:['q:2:34']},
  {q:"Where did Adam and his wife live before coming down to earth?",c:["In Paradise","In Mecca","In Egypt","In Jerusalem"],b:0,e:"“Dwell, you and your wife, in Paradise.”",s:['q:2:35']},
  {q:"Which prophet built the ark at Allah's command?",c:["Nuh (Noah)","Yunus (Jonah)","Sulayman (Solomon)","Isa (Jesus)"],b:0,e:"Nuh built the ark under Allah's eyes and according to His inspiration.",s:['q:11:37']},
  {q:"According to the Qur'an, how long did Nuh stay among his people?",c:["950 years","40 years","100 years","313 years"],b:0,e:"“A thousand years minus fifty years.”",s:['q:29:14']},
  {q:"Who was saved in Nuh's ark?",c:["Nuh, the believers and pairs of animals","All of his people","Only the animals","No one"],b:0,e:"Allah commanded him to load a pair of every kind, his family and the believers.",s:['q:11:40']},
  {q:"Did Nuh's son board the ark?",c:["No, he refused and was drowned","Yes, he was the first","Yes, at the very end","Nuh had no son"],b:0,e:"He thought he could take refuge on a mountain, but the waves swept him away.",s:['q:11:43']},
  {q:"According to Muslim tradition, what was the name of Adam's wife?",c:["Hawwa' (Eve)","Maryam","Asiya","Hajar"],b:0,e:"The Qur'an mentions her without naming her; her name comes from the Sunnah.",s:['f:hawwa']}
 ]},
'pr-ibrahim':{titre:"Ibrahim, the friend of Allah",
 texte:["Ibrahim (Abraham) refused to worship the idols of his people. He was thrown into a great fire, but Allah commanded the fire to be coolness and safety for him.",
  "Allah took him as an intimate friend (khalil). He is the father of two prophets: Isma'il and Ishaq.",
  "With his son Isma'il, he raised the foundations of the Kaaba. The sacrifice of Eid al-Adha recalls his obedience to Allah."],
 retenir:"Ibrahim, the friend of Allah, saved from the fire, builder of the Kaaba with Isma'il.",
 sources:['q:21:69','q:4:125','q:2:127'],
 quiz:[
  {q:"Which prophet raised the foundations of the Kaaba with his son Isma'il?",c:["Ibrahim (Abraham)","Musa (Moses)","Dawud (David)","Adam"],b:0,e:"Ibrahim and his son Isma'il raised the foundations of the Kaaba.",s:['q:2:127']},
  {q:"What happened to Ibrahim when his people threw him into the fire?",c:["Allah made the fire cool and harmless for him","He ran away","He was injured","He was saved by the rain"],b:0,e:"“O fire, be coolness and safety upon Abraham.”",s:['q:21:69']},
  {q:"What title does the Qur'an give to the prophet Ibrahim?",c:["The intimate friend of Allah (Khalil)","The Seal of the Prophets","The one to whom Allah spoke","The Spirit of Allah"],b:0,e:"“And Allah took Abraham as an intimate friend.”",s:['q:4:125']},
  {q:"Who are Ibrahim's two sons who were prophets?",c:["Isma'il and Ishaq","Musa and Harun","Dawud and Sulayman","Yahya and Isa"],b:0,e:"Ibrahim thanked Allah for giving him Isma'il and Ishaq in his old age.",s:['q:14:39']},
  {q:"What did Ibrahim's people do that he refused to do?",c:["Worship statues","Fast","Give charity","Make the pilgrimage"],b:0,e:"He asked them: “What are these statues to which you are devoted?”",s:['q:21:52']},
  {q:"With what did Allah ransom Ibrahim's son at the moment of the sacrifice?",c:["With a great sacrifice (an animal to sacrifice)","With a gift of gold","With his father's fasting","With a night prayer"],b:0,e:"Tradition specifies that it was a ram.",s:['q:37:107']},
  {q:"Which festival recalls Ibrahim's obedience to Allah?",c:["Eid al-Adha","Eid al-Fitr","The 1st of Muharram","The Mawlid"],b:0,e:"The sacrifice of Eid al-Adha commemorates his trial.",s:['q:37:107']},
  {q:"According to the Qur'an, how is Ibrahim described?",c:["A pure monotheist (hanif), neither Jewish nor Christian","A king of Babylon","An angel","A poet"],b:0,e:"He was entirely submitted to Allah.",s:['q:3:67']},
  {q:"Which son helped Ibrahim raise the foundations of the Kaaba?",c:["Isma'il","Ishaq","Ya'qub","Yusuf"],b:0,e:"Ibrahim and Isma'il raised the foundations of the House together.",s:['q:2:127']},
  {q:"According to the Qur'an, what is the first House of worship established for humankind?",c:["The one at Bakkah (Mecca)","The one in Jerusalem","The one in Medina","The one in Ta'if"],b:0,e:"Bakkah is a name for Mecca.",s:['q:3:96']}
 ]},
'pr-yunus':{titre:"Yunus, Yusuf and Sulayman",
 texte:["Yunus (Jonah) was swallowed by a great fish. In the darkness, he called upon Allah, who saved him from distress.",
  "The story of Yusuf (Joseph), betrayed by his brothers and later a minister in Egypt, fills the whole of surah 12: “the best of stories”.",
  "Sulayman (Solomon), son of Dawud, was given an immense kingdom and understood the language of birds and ants."],
 retenir:"Yunus and the fish. Yusuf, surah 12. Sulayman and the language of animals.",
 sources:['q:37:142','q:12:3','q:27:18'],
 quiz:[
  {q:"Which prophet was swallowed by a great fish?",c:["Yunus (Jonah)","Yusuf (Joseph)","Ayyub (Job)","Lut (Lot)"],b:0,e:"Yunus was swallowed by the fish, then Allah saved him.",s:['q:37:142']},
  {q:"Which surah of the Qur'an tells the whole story of the prophet Yusuf (Joseph)?",c:["Surah 12, Yusuf","Surah 1, Al-Fatiha","Surah 36, Ya-Sin","Surah 112, Al-Ikhlas"],b:0,e:"Surah 12 is named after him.",s:['q:12:3']},
  {q:"Which prophet understood the language of ants?",c:["Sulayman (Solomon)","Salih","Hud","Zakariyya"],b:0,e:"Sulayman heard an ant warning the others, and he smiled at its words.",s:['q:27:18']},
  {q:"Which supplication did Yunus say in the belly of the fish?",c:["“Lâ ilâha illâ anta, subḥânaka, innî kuntu mina ẓ-ẓâlimîn”","“Bismi Llâh”","“Allâhu akbar”","“Rabbanâ âtinâ”"],b:0,e:"“There is no god but You; glory be to You. Indeed, I have been of the wrongdoers.”",s:['q:21:87']},
  {q:"How did Allah answer Yunus's supplication?",c:["He saved him from distress","He left him in the fish","He left him in the fish for three years","He did not answer"],b:0,e:"“So We responded to him and saved him from the distress.”",s:['q:21:88']},
  {q:"In his childhood dream, how many stars did Yusuf see prostrating to him?",c:["Eleven, with the sun and the moon","Seven","Twelve","Only one"],b:0,e:"Eleven stars, the sun and the moon.",s:['q:12:4']},
  {q:"Who threw Yusuf to the bottom of a well?",c:["His brothers","Pharaoh","Some merchants","His father"],b:0,e:"His jealous brothers decided to throw him to the bottom of the well.",s:['q:12:15']},
  {q:"What does the Qur'an call the story of Yusuf?",c:["The best of stories","The story of the fire","The book of wisdom","The story of the ark"],b:0,e:"“We relate to you the best of stories.”",s:['q:12:3']},
  {q:"Which prophet was given knowledge of the language of birds?",c:["Sulayman","Yunus","Nuh","Hud"],b:0,e:"“We have been taught the language of birds,” said Sulayman.",s:['q:27:16']},
  {q:"Who was Sulayman's father, who was also a prophet and a king?",c:["Dawud (David)","Ibrahim","Ya'qub","Musa"],b:0,e:"“And Solomon inherited from David.”",s:['q:27:16']}
 ]},
'pr-musa':{titre:"Musa, the one to whom Allah spoke",
 texte:["Musa (Moses) was born in Egypt, at a time when Pharaoh was persecuting the Children of Israel. Inspired by Allah, his mother placed him on the river, and Pharaoh's household took him in.",
  "Allah spoke to him directly and sent him to Pharaoh with his brother Harun, and with miracles, such as his staff that turned into a snake.",
  "Allah parted the sea to save Musa and his people, and Pharaoh was drowned. Musa is the prophet mentioned most often in the Qur'an."],
 retenir:"Musa, saved from the waters, Kalim Allah, the parted sea.",
 sources:['q:28:7','q:4:164','q:26:63'],
 quiz:[
  {q:"In which country was the prophet Musa (Moses) born?",c:["In Egypt","In Arabia","In Iraq","In Yemen"],b:0,e:"He was born in Egypt, during Pharaoh's reign.",s:['q:28:7']},
  {q:"What did Musa's mother do to protect him from Pharaoh?",c:["She placed him on the river","She hid him in a cave","She fled to the desert","She entrusted him to a shepherd"],b:0,e:"Allah inspired her to cast him into the river, without fear.",s:['q:28:7']},
  {q:"Who took in baby Musa from the river?",c:["Pharaoh's household","Some fishermen","Ibrahim","A king of Yemen"],b:0,e:"Pharaoh's people picked him up.",s:['q:28:8']},
  {q:"Which prophet is called “Kalim Allah”, the one to whom Allah spoke directly?",c:["Musa","Ibrahim","Isa","Nuh"],b:0,e:"“And Allah spoke to Moses with direct speech.”",s:['q:4:164']},
  {q:"What did Musa's staff become when he threw it on the ground?",c:["A snake","A tree","A dove","A sword"],b:0,e:"“So he threw it down, and suddenly it was a snake, moving swiftly.”",s:['q:20:20']},
  {q:"What happened when Musa struck the sea with his staff?",c:["It split in two","It turned into sand","It dried up all at once","Nothing"],b:0,e:"Each part was like a huge mountain.",s:['q:26:63']},
  {q:"What happened to Pharaoh and his army, who were chasing Musa?",c:["They were drowned by the sea","They converted","They went back to Egypt","They crossed over too"],b:0,e:"Allah saved Musa and those with him, and drowned the others.",s:['q:26:66']},
  {q:"What was the name of Musa's brother, who helped him in his mission?",c:["Harun (Aaron)","Yusuf","Ishaq","Yahya"],b:0,e:"Musa asked Allah to give him his brother Harun as a helper.",s:['q:20:30']},
  {q:"To which king did Allah send Musa?",c:["Pharaoh","Nimrod","The king of Sheba","Goliath"],b:0,e:"“Go to Pharaoh. Indeed, he has transgressed.”",s:['q:20:24']},
  {q:"Which prophet is mentioned by name most often in the Qur'an?",c:["Musa","Muhammad ﷺ","Ibrahim","Nuh"],b:0,e:"Musa is named more than 130 times in the Qur'an.",s:['f:musa']}
 ]},
'pr-isa':{titre:"Isa and Maryam",
 texte:["Maryam (Mary), the mother of Isa, is the only woman named in the Qur'an. Allah chose her above the women of the worlds, and a surah bears her name.",
  "Isa (Jesus) was born without a father, by the will of Allah, just as Adam was created without a father or mother. As a baby, he spoke in the cradle.",
  "For Muslims, Isa is a great prophet and messenger of Allah, the Messiah, to whom the Injil (Gospel) was revealed."],
 retenir:"Maryam, chosen among women. Isa, born without a father, prophet and Messiah.",
 sources:['q:3:42','q:3:59','q:19:30'],
 quiz:[
  {q:"Who is the only woman named in the Qur'an?",c:["Maryam","Khadijah","Asiya","Hawwa'"],b:0,e:"Maryam is the only woman mentioned by name; surah 19 bears her name.",s:['f:maryam']},
  {q:"What does the Qur'an say about Maryam?",c:["Allah chose her above the women of the worlds","She was a queen of Egypt","She was a prophetess in Medina","The Qur'an does not mention her"],b:0,e:"The angels told her that Allah had chosen and purified her.",s:['q:3:42']},
  {q:"How was the prophet Isa (Jesus) born?",c:["Without a father, by the will of Allah","Like everyone else","In Pharaoh's palace","In Mecca"],b:0,e:"Allah said “Be”, and he was.",s:['q:3:59']},
  {q:"To whose creation does the Qur'an compare the creation of Isa?",c:["To Adam's","To the angels'","To Nuh's","To Iblis's"],b:0,e:"Adam was created without a father or mother; Isa without a father.",s:['q:3:59']},
  {q:"What miracle did Isa perform as a baby?",c:["He spoke in the cradle","He walked on water","He made the water of Zamzam gush forth","He crossed the sea"],b:0,e:"He defended his mother by speaking from the cradle.",s:['q:19:30']},
  {q:"According to the Qur'an, what were the first words of baby Isa?",c:["“I am the servant of Allah”","“I am a king”","“I am an angel”","“I am the son of Zakariyya”"],b:0,e:"“Indeed, I am the servant of Allah. He has given me the Scripture and made me a prophet.”",s:['q:19:30']},
  {q:"What title does the Qur'an give to Isa?",c:["Al-Masih, the Messiah","Al-Khalil","The Seal of the Prophets","Kalim Allah"],b:0,e:"The angels announce to Maryam: “his name will be the Messiah, Isa, son of Mary”.",s:['q:3:45']},
  {q:"Which book did Allah reveal to the prophet Isa?",c:["The Injil (Gospel)","The Tawrat (Torah)","The Zabur (Psalms)","The Qur'an"],b:0,e:"“And We gave him the Gospel, in which was guidance and light.”",s:['q:5:46']},
  {q:"For Muslims, who is Isa?",c:["A prophet and messenger of Allah","A deity","An angel","A king of Jerusalem"],b:0,e:"He presents himself as a servant of Allah and a prophet.",s:['q:19:30']},
  {q:"Who was sent to Maryam to announce the birth of Isa?",c:["The Spirit of Allah, the angel Jibril","Zakariyya","Yahya","The angel Mika'il"],b:0,e:"Scholars explain that “Our Spirit” refers to the angel Jibril.",s:['q:19:19']}
 ]},
'pr-muhammad':{titre:"Muhammad ﷺ, the last prophet",
 texte:["Muhammad ﷺ was born in Mecca around 570, the “Year of the Elephant”, into the tribe of Quraysh. His father died before he was born; he lost his mother Aminah at the age of 6 and was raised by his grandfather, then by his uncle Abu Talib.",
  "Known for his honesty, he was called al-Amin, “the trustworthy one”. He received the first revelation at the age of 40.",
  "He died in Medina in 632, at the age of 63. Allah sent him as a mercy to the worlds."],
 retenir:"Born in Mecca around 570, revelation at 40, died in Medina at 63.",
 sources:['q:21:107','q:68:4','h:vie'],
 quiz:[
  {q:"In which city was the Prophet Muhammad ﷺ born?",c:["Mecca","Medina","Jerusalem","Ta'if"],b:0,e:"He was born in Mecca around 570.",s:['f:sira']},
  {q:"What is the year of the Prophet's ﷺ birth called?",c:["The Year of the Elephant","The Year of the Hijrah","The Year of Sorrow","The Year of Victory"],b:0,e:"The year when an army that came with elephants attacked Mecca (surah 105).",s:['q:105:1']},
  {q:"What was the name of the Prophet's ﷺ mother?",c:["Aminah","Khadijah","Halimah","Fatimah"],b:0,e:"Aminah bint Wahb died when he was 6 years old.",s:['f:sira']},
  {q:"Which uncle raised and protected the Prophet ﷺ?",c:["Abu Talib","Abu Lahab","Hamzah","Al-Abbas"],b:0,e:"After his grandfather's death, his uncle Abu Talib took care of him.",s:['f:sira']},
  {q:"What nickname did the people of Mecca give the Prophet ﷺ before the revelation?",c:["Al-Amin, the trustworthy one","Al-Faruq","As-Siddiq","Sayf Allah"],b:0,e:"He was known to everyone for his honesty.",s:['f:sira']},
  {q:"At what age did the Prophet ﷺ die?",c:["63","40","70","53"],b:0,e:"Ibn Abbas reports that he died at the age of 63.",s:['h:vie']},
  {q:"In which city did the Prophet ﷺ die?",c:["Medina","Mecca","Jerusalem","Damascus"],b:0,e:"He died in Medina in 632 and is buried there.",s:['f:sira']},
  {q:"According to the Qur'an, why did Allah send Muhammad ﷺ?",c:["As a mercy to the worlds","To be a king","To punish people","For the Arabs alone"],b:0,e:"“And We have not sent you except as a mercy to the worlds.”",s:['q:21:107']},
  {q:"What does the Qur'an say about the Prophet's ﷺ character?",c:["He is of an exalted standard of character","He is harsh","He is indifferent","The Qur'an does not mention it"],b:0,e:"“And indeed, you are of a great moral character.”",s:['q:68:4']},
  {q:"Which tribe did the Prophet ﷺ belong to?",c:["Quraysh","Aws","Khazraj","Thaqif"],b:0,e:"Quraysh, the great tribe of Mecca.",s:['f:sira']}
 ]},
'pr-livres':{titre:"The revealed books and faith",
 texte:["Allah revealed books to some of the prophets: the Tawrat (Torah) to Musa, the Zabur (Psalms) to Dawud, the Injil (Gospel) to Isa, and the Qur'an to Muhammad ﷺ.",
  "The Qur'an names 25 prophets, but Allah sent many more. The believer believes in all of them, without making distinctions.",
  "Faith (iman) rests on six pillars: believing in Allah, His angels, His books, His messengers, the Last Day and divine decree."],
 retenir:"Tawrat, Zabur, Injil, Qur'an. Six pillars of faith.",
 sources:['q:5:44','q:2:285','h:jibril'],
 quiz:[
  {q:"Which book did Allah reveal to the prophet Musa (Moses)?",c:["The Tawrat (Torah)","The Zabur (Psalms)","The Injil (Gospel)","The Qur'an"],b:0,e:"The Tawrat to Musa, the Zabur to Dawud, the Injil to Isa, the Qur'an to Muhammad ﷺ.",s:['q:5:44']},
  {q:"How many prophets are mentioned by name in the Qur'an?",c:["25","12","40","313"],b:0,e:"25 prophets are named; 18 of them are mentioned together in Surah Al-An'am.",s:['f:prophetes25']},
  {q:"Which prophet does the Qur'an call “the Seal of the Prophets”, meaning the last one?",c:["Muhammad ﷺ","Isa (Jesus)","Musa (Moses)","Ibrahim (Abraham)"],b:0,e:"Muhammad ﷺ is the last of the prophets.",s:['q:33:40']},
  {q:"Which book was revealed to the prophet Dawud (David)?",c:["The Zabur (Psalms)","The Tawrat","The Injil","The Scrolls of Ibrahim"],b:0,e:"“And to David We gave the Zabur.”",s:['q:4:163']},
  {q:"Is believing in the revealed books part of a Muslim's faith?",c:["Yes, it is a pillar of faith","No, only in the Qur'an","No, it is optional","Only during Ramadan"],b:0,e:"The believers believe in Allah, His angels, His books and His messengers.",s:['q:2:285']},
  {q:"How many pillars of faith (iman) are there?",c:["6","5","4","10"],b:0,e:"Allah, the angels, the books, the messengers, the Last Day and divine decree.",s:['h:jibril']},
  {q:"Which of these is NOT a pillar of faith (iman)?",c:["Fasting in Ramadan","Belief in the angels","Belief in the Last Day","Belief in the books"],b:0,e:"Fasting is a pillar of Islam (practice), not of faith (belief).",s:['h:jibril']},
  {q:"Which book has Allah promised to preserve?",c:["The Qur'an","The Tawrat","The Zabur","All the books of kings"],b:0,e:"“And indeed, We will be its guardian.”",s:['q:15:9']},
  {q:"Does the Qur'an tell the story of every messenger sent by Allah?",c:["No, only some of them","Yes, all of them","It tells none of them","Only the Arab ones"],b:0,e:"“There are messengers whose stories We have related to you, and messengers whose stories We have not related to you.”",s:['q:4:164']},
  {q:"According to the Qur'an, do the believers make distinctions between the messengers in their faith?",c:["No, they believe in all of them","Yes, they believe in only one","Yes, they reject the earlier ones","They believe in none of them"],b:0,e:"“We make no distinction between any of His messengers.”",s:['q:2:285']}
 ]},

/* ===================== HISTORY & COMPANIONS ===================== */
'h-khadija':{titre:"Khadijah and the beginnings of Islam",
 texte:["Khadijah was a respected businesswoman in Mecca. She married the Prophet ﷺ, who was then 25 years old.",
  "After the first revelation, it was she who comforted him and was the first to believe in him. She took him to see her cousin Waraqah ibn Nawfal.",
  "Among the first Muslims were Abu Bakr, Ali, Zayd ibn Harithah and Bilal. For 13 years in Mecca, the Muslims were persecuted; Sumayyah was the first martyr."],
 retenir:"Khadijah, the first to believe. 13 years of preaching in Mecca.",
 sources:['h:hira','f:debuts'],
 quiz:[
  {q:"Who was the Prophet's ﷺ first wife?",c:["Khadijah","Aisha","Hafsah","Zaynab"],b:0,e:"Khadijah was the first person to believe in his message.",s:['h:hira']},
  {q:"Who comforted the Prophet ﷺ right after the first revelation in the cave of Hira?",c:["Khadijah","Abu Bakr","Ali","Bilal"],b:0,e:"He went back to Khadijah, who reassured him.",s:['h:hira']},
  {q:"What was Khadijah's occupation in Mecca?",c:["Trade","Medicine","Poetry","Camel breeding"],b:0,e:"She was a wealthy and respected businesswoman.",s:['f:debuts']},
  {q:"How old was the Prophet ﷺ when he married Khadijah?",c:["25","40","18","30"],b:0,e:"He was 25 years old.",s:['f:debuts']},
  {q:"To whom did Khadijah take the Prophet ﷺ after the first revelation?",c:["Her cousin Waraqah ibn Nawfal","Abu Talib","Abu Bakr","The king of Abyssinia"],b:0,e:"Waraqah knew the earlier Scriptures.",s:['h:hira']},
  {q:"Which young boy was among the first to embrace Islam?",c:["Ali ibn Abi Talib","Umar","Khalid","Mu'awiyah"],b:0,e:"Ali, the Prophet's ﷺ cousin, was still a child.",s:['f:debuts']},
  {q:"For roughly how many years did the Prophet ﷺ preach in Mecca before the Hijrah?",c:["13 years","3 years","23 years","40 years"],b:0,e:"Ibn Abbas reports that he stayed in Mecca for 13 years after the revelation.",s:['h:vie']},
  {q:"Which friend of the Prophet ﷺ was the first adult man to embrace Islam?",c:["Abu Bakr","Umar","Uthman","Hamzah"],b:0,e:"Abu Bakr believed in him without hesitation.",s:['f:debuts']},
  {q:"Which former slave, persecuted for his faith, became the first muezzin of Islam?",c:["Bilal ibn Rabah","Zayd ibn Harithah","Salman","Anas"],b:0,e:"His voice carried far: the Prophet ﷺ entrusted him with the adhan.",s:['h:adhan']},
  {q:"What was the name of the first martyr of Islam?",c:["Sumayyah","Khadijah","Fatimah","Asma'"],b:0,e:"Sumayyah, the mother of Ammar, was killed for her faith in Mecca.",s:['f:debuts']}
 ]},
'h-hegire':{titre:"The Hijrah",
 texte:["In 622, facing persecution, the Prophet ﷺ left Mecca for Medina, then called Yathrib: this is the Hijrah. It marks year 1 of the Muslim calendar.",
  "During the journey, he hid in the cave of Thawr with his friend Abu Bakr.",
  "In Medina, he was welcomed by the Ansar (the “Helpers”), who shared their wealth with the Muhajirun (the “Emigrants”). He built his mosque there."],
 retenir:"622: the Hijrah, year 1. Muhajirun and Ansar.",
 sources:['q:9:40','f:hegire'],
 quiz:[
  {q:"What is the Hijrah?",c:["The Prophet's ﷺ migration from Mecca to Medina","The first pilgrimage","A battle","The Prophet's ﷺ birth"],b:0,e:"It marks year 1 of the Muslim calendar.",s:['f:hegire']},
  {q:"Which Companion was with the Prophet ﷺ in the cave during the Hijrah?",c:["Abu Bakr as-Siddiq","Umar ibn al-Khattab","Ali ibn Abi Talib","Bilal"],b:0,e:"Abu Bakr was “the second of the two” in the cave.",s:['q:9:40']},
  {q:"In which year did the Hijrah take place?",c:["622","570","632","610"],b:0,e:"The Hijrah took place in 622 CE.",s:['f:hegire']},
  {q:"In which cave did the Prophet ﷺ hide during the Hijrah?",c:["The cave of Thawr","The cave of Hira","The cave of Uhud","The cave of Badr"],b:0,e:"Thawr is south of Mecca; Hira, the place of the first revelation, is to the north.",s:['f:hegire']},
  {q:"What was the old name of Medina?",c:["Yathrib","Bakkah","Ta'if","Quba'"],b:0,e:"The Qur'an mentions this name: “O people of Yathrib”.",s:['q:33:13']},
  {q:"What are the people of Medina who welcomed the Muslims called?",c:["The Ansar","The Muhajirun","Quraysh","The Children of Israel"],b:0,e:"Ansar means “the Helpers”.",s:['q:9:100']},
  {q:"What are the Muslims who emigrated from Mecca to Medina called?",c:["The Muhajirun","The Ansar","The Khawarij","The Bedouins"],b:0,e:"Muhajirun means “the Emigrants”.",s:['q:9:100']},
  {q:"According to the Qur'an, what did the Prophet ﷺ say to Abu Bakr in the cave?",c:["“Do not grieve; indeed Allah is with us”","“Let's flee quickly”","“Let's go back to Mecca”","“Let's fight them”"],b:0,e:"It is verse 40 of Surah At-Tawbah.",s:['q:9:40']},
  {q:"Under which caliph was the Hijri calendar adopted?",c:["Umar","Abu Bakr","Uthman","Ali"],b:0,e:"Umar made the Hijrah the starting point of the calendar.",s:['f:hegire']},
  {q:"What did the Prophet ﷺ build when he arrived in Medina?",c:["His mosque","A palace","A fortress","A market"],b:0,e:"The Prophet's Mosque (al-Masjid an-Nabawi).",s:['f:hegire']}
 ]},
'h-badr':{titre:"The Battle of Badr",
 texte:["On the 17th of Ramadan in year 2 of the Hijrah (624), the Muslims faced the army of Quraysh near the wells of Badr.",
  "There were about 313 of them, against nearly 1,000 fighters. Allah supported them with angels, and they won the victory.",
  "The Qur'an calls this day “the Day of the Criterion” (yawm al-furqan), the day when truth was distinguished from falsehood."],
 retenir:"17th of Ramadan, year 2: Badr, 313 against 1,000, the Day of the Criterion.",
 sources:['q:3:123','q:8:9','q:8:41'],
 quiz:[
  {q:"In which month did the Battle of Badr take place?",c:["Ramadan","Muharram","Dhul-Hijjah","Rajab"],b:0,e:"On the 17th of Ramadan in year 2 of the Hijrah.",s:['f:badr']},
  {q:"In which year of the Hijrah did the Battle of Badr take place?",c:["Year 2","Year 8","Year 10","Year 1"],b:0,e:"In 624 CE.",s:['f:badr']},
  {q:"Roughly how many Muslims fought at Badr?",c:["About 313","About 3,000","About 10,000","About 50"],b:0,e:"There were about 313 of them.",s:['f:badr']},
  {q:"Roughly how many fighters did the army of Quraysh have at Badr?",c:["Nearly 1,000","Nearly 100","Nearly 10,000","Nearly 300"],b:0,e:"The Meccans outnumbered them three to one.",s:['f:badr']},
  {q:"According to the Qur'an, how did Allah support the Muslims at Badr?",c:["With angels","With a sandstorm","With reinforcements from Persia","With rain alone"],b:0,e:"Allah answered their call by sending angels.",s:['q:8:9']},
  {q:"According to Surah Al-Anfal, how many angels did Allah promise to send as reinforcements at Badr?",c:["A thousand","A hundred","Ten","Three hundred"],b:0,e:"“Indeed, I will reinforce you with a thousand angels, following one another.”",s:['q:8:9']},
  {q:"What does the Qur'an call the day of Badr?",c:["The Day of the Criterion (yawm al-furqan)","The Day of Resurrection","The day of Eid","The day of the Hijrah"],b:0,e:"The day when truth was distinguished from falsehood.",s:['q:8:41']},
  {q:"Which tribe did the Muslims fight at Badr?",c:["Quraysh","The Romans","The Persians","The Ansar"],b:0,e:"The army of Quraysh came from Mecca.",s:['f:badr']},
  {q:"On which day of Ramadan did the Battle of Badr take place?",c:["The 17th","The 27th","The 1st","The 10th"],b:0,e:"The 17th of Ramadan, year 2.",s:['f:badr']},
  {q:"According to the Qur'an, what situation were the Muslims in at Badr?",c:["They were weak and humbled","They were very numerous","They were wealthy","They were on horseback"],b:0,e:"“And Allah had already given you victory at Badr while you were weak and humbled.”",s:['q:3:123']}
 ]},
'h-fath':{titre:"The conquest of Mecca",
 texte:["In year 8 of the Hijrah (630), during the month of Ramadan, the Prophet ﷺ entered Mecca with about 10,000 Muslims, almost without fighting.",
  "He forgave his former enemies and cleansed the Kaaba of its 360 idols, reciting: “Truth has come and falsehood has vanished.”",
  "Surah An-Nasr announces this help from Allah and people entering Islam in crowds."],
 retenir:"Ramadan, year 8: Mecca opened, the idols broken, forgiveness granted.",
 sources:['q:17:81','h:idoles','q:110:1'],
 quiz:[
  {q:"In which year of the Hijrah was Mecca conquered?",c:["Year 8","Year 2","Year 1","Year 11"],b:0,e:"In 630 CE.",s:['f:fath']},
  {q:"In which month did the conquest of Mecca take place?",c:["Ramadan","Shawwal","Dhul-Hijjah","Muharram"],b:0,e:"The conquest of Mecca took place in Ramadan.",s:['f:fath']},
  {q:"Roughly how many Muslims accompanied the Prophet ﷺ at the conquest of Mecca?",c:["About 10,000","About 313","About 1,000","About 100"],b:0,e:"An army of about 10,000 men.",s:['f:fath']},
  {q:"How many idols surrounded the Kaaba on the day of the conquest of Mecca?",c:["360","12","99","1,000"],b:0,e:"Abdullah ibn Mas'ud reports that there were 360 of them.",s:['h:idoles']},
  {q:"Which verse did the Prophet ﷺ recite while knocking down the idols of the Kaaba?",c:["“Truth has come and falsehood has vanished”","“In the name of Allah”","“Say: He is Allah, the One”","“Read!”"],b:0,e:"It is verse 81 of Surah Al-Isra'.",s:['q:17:81','h:idoles']},
  {q:"How did the Prophet ﷺ treat his former Meccan enemies after the conquest?",c:["He forgave them","He drove them out","He imprisoned them","He exiled them to Abyssinia"],b:0,e:"He granted a general pardon to the people of Mecca.",s:['f:fath']},
  {q:"Which surah announces “the help of Allah and the victory”?",c:["An-Nasr (110)","Al-Fath (48)","Al-Fil (105)","Al-Kawthar (108)"],b:0,e:"“When the help of Allah and the victory come.”",s:['q:110:1']},
  {q:"According to Surah An-Nasr, how did people enter Islam?",c:["In crowds","One by one, in secret","By force","No one entered"],b:0,e:"“And you see the people entering into the religion of Allah in multitudes.”",s:['q:110:2']},
  {q:"Was the conquest of Mecca achieved through a great battle?",c:["No, almost without fighting","Yes, the greatest in history","Yes, lasting a year","Yes, at the foot of Mount Uhud"],b:0,e:"The city was opened peacefully, almost without any clash.",s:['f:fath']},
  {q:"What does Surah An-Nasr ask for after the victory?",c:["To glorify Allah and ask His forgiveness","To perform Hajj immediately","To fast for three days","To rebuild the Kaaba"],b:0,e:"“Then exalt with praise of your Lord and ask forgiveness of Him.”",s:['q:110:3']}
 ]},
'h-califes':{titre:"The first four caliphs",
 texte:["After the Prophet's ﷺ death in 632, four caliphs succeeded one another: Abu Bakr, Umar, Uthman and Ali. They are called the “rightly guided caliphs”.",
  "Abu Bakr had the Qur'an gathered into a single compilation by Zayd ibn Thabit. Under Umar, Islam spread and the Hijri calendar was adopted.",
  "Uthman had the Qur'an copied into several copies sent to the provinces. Ali, the Prophet's ﷺ cousin and son-in-law, was the fourth caliph."],
 retenir:"Abu Bakr, Umar, Uthman, Ali: the four rightly guided caliphs.",
 sources:['h:compilation','h:copies','f:califes'],
 quiz:[
  {q:"Who was the first caliph after the Prophet's ﷺ death?",c:["Abu Bakr","Umar","Ali","Uthman"],b:0,e:"Abu Bakr, then Umar, Uthman and Ali.",s:['f:califes']},
  {q:"How many “rightly guided caliphs” succeeded the Prophet ﷺ?",c:["4","3","5","12"],b:0,e:"They are called al-khulafa' ar-rashidun.",s:['f:califes']},
  {q:"What is the order of the first four caliphs?",c:["Abu Bakr, Umar, Uthman, Ali","Ali, Umar, Abu Bakr, Uthman","Umar, Abu Bakr, Ali, Uthman","Uthman, Ali, Umar, Abu Bakr"],b:0,e:"From 632 to 661.",s:['f:califes']},
  {q:"Under which caliph was the Qur'an first gathered into a single compilation?",c:["Abu Bakr","Umar","Uthman","Ali"],b:0,e:"After the Battle of Yamamah, where many reciters were killed.",s:['h:compilation']},
  {q:"Which Companion was tasked with gathering the Qur'an under Abu Bakr?",c:["Zayd ibn Thabit","Bilal","Khalid ibn al-Walid","Salman"],b:0,e:"Zayd ibn Thabit had been a scribe of the revelation.",s:['h:compilation']},
  {q:"Which caliph had the Qur'an copied into several copies sent to the provinces?",c:["Uthman","Abu Bakr","Umar","Ali"],b:0,e:"To unify the recitation throughout the Muslim world.",s:['h:copies']},
  {q:"How was Ali related to the Prophet ﷺ?",c:["His cousin and son-in-law","His brother","His uncle","His grandfather"],b:0,e:"Ali was the husband of Fatimah, the Prophet's ﷺ daughter.",s:['f:califes']},
  {q:"Which caliph was nicknamed “al-Faruq”, the one who distinguishes truth from falsehood?",c:["Umar","Abu Bakr","Uthman","Ali"],b:0,e:"Umar ibn al-Khattab.",s:['f:califes']},
  {q:"Which caliph was nicknamed “as-Siddiq”, the truthful one?",c:["Abu Bakr","Umar","Uthman","Ali"],b:0,e:"Abu Bakr immediately believed everything the Prophet ﷺ reported.",s:['f:califes']},
  {q:"Which caliph married two of the Prophet's ﷺ daughters, one after the other?",c:["Uthman","Umar","Abu Bakr","Ali"],b:0,e:"Hence his nickname “Dhun-Nurayn”, the man of the two lights.",s:['f:califes']}
 ]}
},

/* Reference notes (historical or practical sources, without Arabic text) */
faits:{
 mois:{titre:"Reference",texte:"The 12 Hijri months: Muharram, Safar, Rabi' al-Awwal, Rabi' ath-Thani, Jumada al-Ula, Jumada al-Akhirah, Rajab, Sha'ban, Ramadan, Shawwal, Dhul-Qa'dah, Dhul-Hijjah."},
 jeune2:{titre:"Historical reference",texte:"Fasting in Ramadan was prescribed in Medina, in year 2 of the Hijrah (624)."},
 conditions:{titre:"Reference",texte:"Scholars set the following conditions for fasting to be obligatory: being Muslim, having reached puberty, being of sound mind and being able to fast."},
 aid:{titre:"Reference",texte:"Islam has two festivals: Eid al-Fitr, on the 1st of Shawwal, at the end of Ramadan, and Eid al-Adha, on the 10th of Dhul-Hijjah, during Hajj."},
 shahada:{titre:"Reference",texte:"Text of the shahada: “Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh” — “I bear witness that there is no god but Allah, and I bear witness that Muhammad is the Messenger of Allah”."},
 rakat:{titre:"Transmitted practice",texte:"The number of units in each prayer comes from the practice of the Prophet ﷺ, passed down by all Muslims: Fajr 2, Dhuhr 4, Asr 4, Maghrib 3, Isha 4, making 17 rak'ahs a day."},
 zakat:{titre:"Reference",texte:"Zakat on money is 2.5% (one fortieth) of savings that reach the nisab and remain in one's possession for a lunar year (the hawl). Sadaqah is voluntary charity. For specific cases, ask a scholar."},
 hajj:{titre:"Reference",texte:"Hajj takes place from the 8th to the 13th of Dhul-Hijjah. The pilgrim enters ihram (men wear two pieces of unstitched white cloth), performs tawaf (seven circuits around the Kaaba) and sa'y (seven trips between Safa and Marwa). The 9th is the day of Arafah, the 10th is Eid al-Adha."},
 coran:{titre:"Reference",texte:"The Qur'an has 114 surahs and 6,236 verses according to the most widespread count. It is divided into 30 parts (juz'). A verse is called an ayah. Surahs revealed before the Hijrah are called Meccan, those revealed after it Medinan. The longest is Al-Baqarah (286 verses)."},
 tawba:{titre:"Reference",texte:"Surah At-Tawbah (9) is the only one of the 114 surahs that does not begin with “Bismi Llâhi r-Raḥmâni r-Raḥîm”."},
 ikhlas:{titre:"Reference",texte:"Al-Ikhlas means “pure monotheism, sincerity”: the surah purifies faith from any association of partners with Allah."},
 hawwa:{titre:"Reference",texte:"The Qur'an mentions Adam's wife without naming her. Her name, Hawwa' (Eve), comes from the Sunnah and the scholars."},
 musa:{titre:"Reference",texte:"Musa is the prophet named most often in the Qur'an: more than 130 times."},
 maryam:{titre:"Reference",texte:"Maryam is the only woman mentioned by name in the Qur'an. Surah 19 bears her name."},
 sira:{titre:"Historical reference",texte:"The Prophet ﷺ was born in Mecca around 570, into the tribe of Quraysh. His father having died before his birth, he lost his mother Aminah at 6 and was raised by his grandfather Abd al-Muttalib, then by his uncle Abu Talib. He was called al-Amin. He died in Medina in 632."},
 prophetes25:{titre:"Reference",texte:"25 prophets are named in the Qur'an. 18 of them are mentioned together in Surah Al-An'am (6), verses 83 to 86."},
 debuts:{titre:"Historical reference",texte:"Khadijah, a wealthy businesswoman, married the Prophet ﷺ when he was 25. Among the very first Muslims: Khadijah, Abu Bakr, Ali (still a child), Zayd ibn Harithah. Bilal, a persecuted slave who was later freed, became the first muezzin. Sumayyah, the mother of Ammar, was the first martyr."},
 hegire:{titre:"Historical reference",texte:"The Hijrah took place in 622. The Prophet ﷺ and Abu Bakr hid in the cave of Thawr. Medina was called Yathrib. The Prophet ﷺ built his mosque there. The Hijri calendar was adopted during the caliphate of Umar."},
 badr:{titre:"Historical reference",texte:"The Battle of Badr took place on the 17th of Ramadan, year 2 (624). About 313 Muslims faced nearly 1,000 fighters from Quraysh."},
 fath:{titre:"Historical reference",texte:"Mecca was opened in Ramadan of year 8 (630), almost without fighting, by about 10,000 Muslims. The Prophet ﷺ granted a general pardon to the people of Mecca."},
 califes:{titre:"Historical reference",texte:"The four rightly guided caliphs: Abu Bakr as-Siddiq (632-634), Umar al-Faruq (634-644), Uthman Dhun-Nurayn (644-656), who married two of the Prophet's ﷺ daughters, Ruqayyah and then Umm Kulthum, and Ali (656-661), the Prophet's ﷺ cousin and the husband of his daughter Fatimah."}
},

/* Summaries shown for long hadiths (the full text remains available) */
resumes:{
 cinq:"During the Night Journey (al-Isra' wal-Mi'raj), fifty prayers were first prescribed, then reduced to five prayers a day.",
 enfants:"Ar-Rubayyi' bint Mu'awwidh relates that the Companions made their young children fast on the day of Ashura, and gave them woollen toys to keep them busy until it was time to break the fast.",
 hira:"Aisha relates that the Prophet ﷺ used to go into retreat in the cave of Hira. The angel came and said to him: “Read!”. He went back to Khadijah, who comforted him, then took him to see her cousin Waraqah ibn Nawfal.",
 regles:"Aisha explains that they were ordered to make up the fasts missed during their periods, but not the prayers.",
 tarawih:"The Prophet ﷺ prayed at night in the mosque during Ramadan; people prayed behind him, more and more of them. Then he stopped coming out, fearing that this prayer would be made obligatory for them.",
 adhan:"The Companion Abdullah ibn Zayd saw the words of the adhan in a dream. The Prophet ﷺ confirmed this dream and asked Bilal to make the call, because his voice carried further.",
 ikhlas:"A man kept reciting Surah Al-Ikhlas and felt it was too little. The Prophet ﷺ said: “It is equal to a third of the Qur'an.”",
 kursi:"The Prophet ﷺ asked Ubayy ibn Ka'b which is the greatest verse in the Book of Allah. He answered: Ayat al-Kursi. The Prophet ﷺ congratulated him on his knowledge.",
 hajj_une:"The Prophet ﷺ announced that Hajj had been prescribed. A man asked: “Every year?” He replied that if he said yes, it would become obligatory every year: it is obligatory once.",
 arafa:"Some people asked the Prophet ﷺ at Arafah about the pilgrimage. He answered: “Hajj is Arafah.”",
 jibril:"The angel Jibril, in human form, asked the Prophet ﷺ about Islam, faith and excellence. Faith (iman): believing in Allah, His angels, His books, His messengers, the Last Day and divine decree, both good and bad.",
 vie:"Ibn Abbas reports that the Prophet ﷺ received the revelation at 40, stayed 13 years in Mecca, emigrated to Medina where he lived for 10 years, and died at 63.",
 idoles:"On the day of the conquest, there were 360 idols around the Kaaba. The Prophet ﷺ struck them with a stick, reciting: “Truth has come and falsehood has vanished.”",
 compilation:"After the Battle of Yamamah, where many reciters were killed, Abu Bakr entrusted Zayd ibn Thabit with gathering the Qur'an into a single compilation.",
 copies:"Uthman, concerned about differences in recitation between the provinces, had the compilation of the Qur'an copied into several copies sent to each region.",
 fitr_but:"Ibn Abbas reports that the Prophet ﷺ prescribed zakat al-fitr to purify the fasting person from idle and indecent talk, and to feed the poor.",
 afw:"Aisha asked what she should say if she knew which night was the Night of Decree. He answered: “Say: Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî” — O Allah, You are the One who pardons, You love to pardon, so pardon me."
}
};
